SELECT *
, (SELECT COUNT(*) FROM shopion.tPrfCompStore C WHERE C.ParentStoreCode = tPrfCompStore.StoreCode AND C.CompCode = tPrfCompStore.CompCode) AS ChildCount
FROM shopion.tPrfCompStore

    AND CompCode = #{pCompCode}

        AND ParentStoreCode = #{pParentStoreCode}
        AND StoreLevel = 0
        AND StoreCode = #{pStoreCode}

SELECT COUNT(*)
FROM shopion.tPrfCompStore

    AND CompCode = #{pCompCode}

        AND ParentStoreCode = #{pParentStoreCode}
        AND StoreLevel = 0
        AND StoreCode = #{pStoreCode}

SELECT *
, (SELECT COUNT(*) FROM shopion.tPrfCompStore C WHERE C.ParentStoreCode = tPrfCompStore.StoreCode AND C.CompCode = tPrfCompStore.CompCode) AS ChildCount
FROM shopion.tPrfCompStore

    AND ParentStoreCode = #{pParentStoreCode}
    AND CompCode = #{pCompCode}

SELECT IFNULL(MAX(StoreCode),'')
FROM shopion.tPrfCompStore

    AND ParentStoreCode = #{parentStoreCode}
    AND CompCode = #{compCode}
    AND StoreLevel = 0

SELECT *
FROM shopion.tPrfCompStore

    AND StoreCode = #{pStoreCode}
    AND CompCode = #{pCompCode}

mapper.update:
UPDATE shopion.tPrfCompStore SET
    StoreName = #{storeName}, StoreDesc = #{storeDesc}, StoreSeq = #{storeSeq},
    State = #{state}, Remark = #{remark},
    ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE CompCode = #{compCode}
AND StoreCode = #{storeCode}

